create table if not exists public.project_control(id uuid primary key default gen_random_uuid(),project_name text not null default 'Proyek Cair',contract_start_date date,contract_end_date date,actual_start_date date,actual_end_date date,status text not null default 'BERJALAN' check(status in ('PERSIAPAN','BERJALAN','DITUNDA','SELESAI','DIBATALKAN')),updated_at timestamptz not null default now(),updated_by uuid references auth.users(id));
insert into public.project_control(project_name) select 'Proyek Cair' where not exists(select 1 from public.project_control);
create table if not exists public.inventory_locations(id uuid primary key default gen_random_uuid(),name text not null unique,location_type text not null default 'GUDANG' check(location_type in ('GUDANG','LAYDOWN','AREA_KERJA','SUPPLIER','LAINNYA')),is_active boolean not null default true,created_at timestamptz not null default now(),created_by uuid references auth.users(id));
create table if not exists public.boq_additions(id uuid primary key default gen_random_uuid(),item_id uuid references public.boq_items(id),addition_code text not null unique,description text not null,quantity numeric(18,4) not null check(quantity>0),uom text not null,unit_rate numeric(18,2) not null default 0 check(unit_rate>=0),requester_type text not null check(requester_type in ('CLIENT','CONTRACTOR')),chargeable_to_client boolean not null,reason text not null,requested_by_name text not null,requested_at timestamptz not null default now(),approval_status text not null default 'DIAJUKAN' check(approval_status in ('DIAJUKAN','DISETUJUI','DITOLAK','DIBATALKAN')),approved_by uuid references auth.users(id),approved_at timestamptz,approval_reference text,billing_status text not null default 'BELUM_DITAGIHKAN' check(billing_status in ('BELUM_DITAGIHKAN','DITAGIHKAN','DIBAYAR','TIDAK_DITAGIHKAN')),billed_at timestamptz,notes text,created_by uuid not null references auth.users(id),created_at timestamptz not null default now(),updated_at timestamptz not null default now(),constraint boq_additions_chargeable_rule check((requester_type='CLIENT' and chargeable_to_client=true and billing_status<>'TIDAK_DITAGIHKAN') or (requester_type='CONTRACTOR' and chargeable_to_client=false and billing_status='TIDAK_DITAGIHKAN')));
create table if not exists public.item_schedules(item_id uuid primary key references public.boq_items(id) on delete restrict,need_start_date date,target_receipt_date date,target_use_start_date date,target_use_end_date date,actual_last_receipt_at timestamptz,actual_last_use_at timestamptz,notes text,updated_by uuid references auth.users(id),updated_at timestamptz not null default now(),constraint item_schedule_date_order check((need_start_date is null or target_receipt_date is null or need_start_date<=target_receipt_date) and (target_use_start_date is null or target_use_end_date is null or target_use_start_date<=target_use_end_date)));
alter table public.inventory_transactions add column if not exists source_name text,destination_name text,source_location_id uuid references public.inventory_locations(id),destination_location_id uuid references public.inventory_locations(id),owner_type text not null default 'KONTRAKTOR' check(owner_type in ('KONTRAKTOR','IMK')),addition_id uuid references public.boq_additions(id),purpose text,recipient_name text,reversal_of uuid references public.inventory_transactions(id),reversed_at timestamptz,reversed_by uuid references auth.users(id);
create index if not exists inventory_tx_addition_idx on public.inventory_transactions(addition_id);
create index if not exists inventory_tx_occurred_idx on public.inventory_transactions(occurred_at desc);
create index if not exists boq_additions_item_idx on public.boq_additions(item_id,requested_at desc);
create index if not exists boq_additions_status_idx on public.boq_additions(approval_status,billing_status);
create index if not exists item_schedules_receipt_idx on public.item_schedules(target_receipt_date);
create or replace function public.enforce_boq_addition_rules() returns trigger language plpgsql set search_path=public as $$ begin if new.requester_type='CLIENT' then new.chargeable_to_client:=true;if new.billing_status='TIDAK_DITAGIHKAN' then new.billing_status:='BELUM_DITAGIHKAN';end if;else new.chargeable_to_client:=false;new.billing_status:='TIDAK_DITAGIHKAN';end if;if new.approval_status='DISETUJUI' and (new.approved_by is null or new.approved_at is null) then new.approved_by:=auth.uid();new.approved_at:=now();end if;new.updated_at:=now();return new;end $$;
drop trigger if exists boq_additions_enforce_rules on public.boq_additions;create trigger boq_additions_enforce_rules before insert or update on public.boq_additions for each row execute function public.enforce_boq_addition_rules();
create or replace function public.capture_udu_audit() returns trigger language plpgsql security definer set search_path=public as $$ declare v_actor uuid;v_old jsonb;v_new jsonb;v_id text;begin v_actor:=auth.uid();if tg_op='DELETE' then v_old:=to_jsonb(old);v_new:=null;v_id:=coalesce(v_old->>'id',v_old->>'item_id',v_old->>'addition_code');elsif tg_op='UPDATE' then v_old:=to_jsonb(old);v_new:=to_jsonb(new);v_id:=coalesce(v_new->>'id',v_new->>'item_id',v_new->>'addition_code');else v_old:=null;v_new:=to_jsonb(new);v_id:=coalesce(v_new->>'id',v_new->>'item_id',v_new->>'addition_code');end if;insert into public.audit_logs(actor_id,action,entity_type,entity_id,details) values(v_actor,'ROW_'||tg_op,tg_table_name,v_id,jsonb_build_object('before',v_old,'after',v_new,'table',tg_table_name,'db_user',session_user));if tg_op='DELETE' then return old;else return new;end if;end $$;
create or replace function public.prevent_ledger_mutation() returns trigger language plpgsql set search_path=public as $$ begin raise exception 'Ledger rows are immutable. Record a reversal/correction transaction instead.';end $$;
drop trigger if exists inventory_transactions_immutable on public.inventory_transactions;create trigger inventory_transactions_immutable before update or delete on public.inventory_transactions for each row execute function public.prevent_ledger_mutation();
drop trigger if exists cash_transactions_immutable on public.cash_transactions;create trigger cash_transactions_immutable before update or delete on public.cash_transactions for each row execute function public.prevent_ledger_mutation();
drop trigger if exists audit_project_control on public.project_control;create trigger audit_project_control after insert or update or delete on public.project_control for each row execute function public.capture_udu_audit();
drop trigger if exists audit_inventory_locations on public.inventory_locations;create trigger audit_inventory_locations after insert or update or delete on public.inventory_locations for each row execute function public.capture_udu_audit();
drop trigger if exists audit_boq_additions on public.boq_additions;create trigger audit_boq_additions after insert or update or delete on public.boq_additions for each row execute function public.capture_udu_audit();
drop trigger if exists audit_item_schedules on public.item_schedules;create trigger audit_item_schedules after insert or update or delete on public.item_schedules for each row execute function public.capture_udu_audit();
drop trigger if exists audit_boq_items on public.boq_items;create trigger audit_boq_items after update or delete on public.boq_items for each row execute function public.capture_udu_audit();
alter table public.project_control enable row level security;alter table public.inventory_locations enable row level security;alter table public.boq_additions enable row level security;alter table public.item_schedules enable row level security;
create policy project_control_read on public.project_control for select to authenticated using(true);create policy project_control_update on public.project_control for update to authenticated using(public.current_user_role() in ('admin','site_manager')) with check(public.current_user_role() in ('admin','site_manager'));
create policy inventory_locations_read on public.inventory_locations for select to authenticated using(true);create policy inventory_locations_manage on public.inventory_locations for all to authenticated using(public.current_user_role() in ('admin','site_manager','storekeeper')) with check(public.current_user_role() in ('admin','site_manager','storekeeper'));
create policy boq_additions_read on public.boq_additions for select to authenticated using(true);create policy boq_additions_insert on public.boq_additions for insert to authenticated with check(public.current_user_role() in ('admin','site_manager'));create policy boq_additions_update on public.boq_additions for update to authenticated using(public.current_user_role() in ('admin','site_manager')) with check(public.current_user_role() in ('admin','site_manager'));
create policy item_schedules_read on public.item_schedules for select to authenticated using(true);create policy item_schedules_manage on public.item_schedules for all to authenticated using(public.current_user_role() in ('admin','site_manager','storekeeper')) with check(public.current_user_role() in ('admin','site_manager','storekeeper'));
grant select on public.project_control,public.inventory_locations,public.boq_additions,public.item_schedules to authenticated;grant insert,update on public.project_control,public.inventory_locations,public.boq_additions,public.item_schedules to authenticated;
revoke all on function public.capture_udu_audit() from public,anon,authenticated;revoke all on function public.prevent_ledger_mutation() from public,anon,authenticated;